    else:
        kb.add(types.InlineKeyboardButton("🔢 Вказати кількість", callback_data=f"ahsrq:{category}:{inventory_id}:{page}"))

    kb.add(types.InlineKeyboardButton("🔙 До списку предметів", callback_data=f"ah_sell_page:{category}:{page}"))
