        row.append(types.InlineKeyboardButton(prefix + label, callback_data=f"ah_hist:{key}:0"))
    kb.row(*row)

    nav = []
    if int(page) > 0:
        nav.append(types.InlineKeyboardButton("⬅️ Назад", callback_data=f"ah_hist:{mode}:{int(page) - 1}"))
    if has_next:
