def _auction_list_short_v1(values, limit=10):
    values = list(values or [])
    if not values:
        return "немає"

    shown = values[:limit]
    text = ", ".join(str(x) for x in shown)
    if len(values) > limit:
        text += f" ... +{len(values) - limit}"
    return text

