        if int(item.get("max_stack") or 1) <= 1:
            conn.execute("UPDATE inventory SET user_id=? WHERE id=? AND user_id=?", (recipient,int(inv["id"]),owner))
        else: _trade_transfer_stack_12_7_0(conn, inv, recipient, quantity, item)
